109	/**
110	 * Builds the magic-link URL for the given landing path, sends the email via Marketing Cloud,
111	 * and writes the API response to the Express response.
112	 */
113	type LoginConfig = {
114	  login?: {
115	    resetPassword?: { landingPath?: string };
116	    passwordless?: { landingPath?: string };
117	  };
118	};
119	
120	export async function sendMagicLinkEmail(
121	  req: SsrReq,
122	  res: SsrRes,
123	  landingPath: string,
124	  emailTemplate: string,
125	  redirectUrl?: string,
126	): Promise<void> {
127	  const { app } = getConfig() as { app: LoginConfig };
128	
129	  // Extract the base URL from the request
130	  const host = req.get('host');
131	  if (!host) throw new Error('Cannot construct magic link: missing Host header');
132	  const base = `${req.protocol}://${host}`;
133	
134	  // Extract the email_id and token from the request body
135	  const { email_id, token } = req.body;
136	
137	  // Construct the magic link URL
138	  let magicLink = `${base}${landingPath}?token=${encodeURIComponent(token)}`;
139	  if (landingPath === app.login?.resetPassword?.landingPath) {
140	    // Add email query parameter for reset password flow
141	    magicLink += `&email=${encodeURIComponent(email_id)}`;
142	  }
143	  if (landingPath === app.login?.passwordless?.landingPath && redirectUrl) {
144	    magicLink += `&redirect_url=${encodeURIComponent(redirectUrl)}`;
145	  }
146	
147	  // Call the emailLink function to send an email with the magic link using Marketing Cloud
148	  const emailLinkResponse = await emailLink(email_id, emailTemplate, magicLink);
149	
150	  // Send the response
151	  res.send(emailLinkResponse);
152	}
