// delivery token actually authenticates for that space/environment, not just
// that it's non-blank.
async function liveCheckContentful(tier) {
  const merged = mergeSharedAndTier(tier);
  if (!merged) return { skipped: true, reason: '.env.shared and/or .env.<tier> not created yet' };

  const deliveryToken = merged.get('CONTENTFUL_DELIVERY_TOKEN');
  const spaceId = merged.get('CONTENTFUL_SPACE_ID');
  const envId = merged.get('CONTENTFUL_ENVIRONMENT_ID');
  if (!deliveryToken || !spaceId || !envId) {
    return {
      skipped: true,
      reason: 'CONTENTFUL_DELIVERY_TOKEN / CONTENTFUL_SPACE_ID / CONTENTFUL_ENVIRONMENT_ID not all filled in',
    };
  }

  const url = `https://cdn.contentful.com/spaces/${spaceId}/environments/${envId}/entries?limit=1`;
  try {
    const res = await fetch(url, {
      headers: { Authorization: `Bearer ${deliveryToken}` },
      signal: AbortSignal.timeout(LIVE_CHECK_TIMEOUT_MS),
    });
    if (res.ok) return { ok: true };
    return { ok: false, message: `HTTP ${res.status} from Contentful Delivery API` };
  } catch (err) {
    if (err.name === 'TimeoutError') return { ok: false, message: `timed out after ${LIVE_CHECK_TIMEOUT_MS}ms` };
    return { ok: false, message: `network error — ${err.message}` };
  }
}

