export async function getSlasToken(siteId) {
  const { COMMERCE_API_SHORT_CODE, COMMERCE_API_ORGANIZATION_ID, COMMERCE_API_CLIENT_ID, PWA_KIT_SLAS_CLIENT_SECRET } =
    process.env;
  const url = `https://${COMMERCE_API_SHORT_CODE}.api.commercecloud.salesforce.com/shopper/auth/v1/organizations/${COMMERCE_API_ORGANIZATION_ID}/oauth2/token`;
  const basicAuth = Buffer.from(`${COMMERCE_API_CLIENT_ID}:${PWA_KIT_SLAS_CLIENT_SECRET}`).toString('base64');

  const response = await fetch(url, {
    method: 'POST',
    headers: {
      Authorization: `Basic ${basicAuth}`,
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: new URLSearchParams({ grant_type: 'client_credentials', channel_id: siteId }).toString(),
    signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
  });

